export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = validators[message.type];
  if (!validator) {
    return {valid: false, error: `Unknown message type: ${message.type}`};
  }

  return validator(message);
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const parsedMessage: Extract<IncomingMessage, {type: 'list_sessions'}> = {type: 'list_sessions'};

  if (message.limit !== undefined && (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0)) {
    return {valid: false, error: 'limit must be a non-negative integer'};
  }
  if (message.limit !== undefined) {
    parsedMessage.limit = message.limit;
  }

  if (message.before !== undefined && (typeof message.before !== 'object' || message.before === null)) {
    return {valid: false, error: 'before must be an object'};
  }
  if (message.before !== undefined) {
    const before = message.before as Record<string, unknown>;

    if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
      return {valid: false, error: 'before.sessionId must be a string of 1-128 chars'};
    }

    const {updatedAt} = before;
    if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') {
      return {valid: false, error: 'before.updatedAt must be string or number'};
    }
    if (typeof updatedAt === 'string' && Number.isNaN(Date.parse(updatedAt))) {
      return {valid: false, error: 'before.updatedAt string must be a valid date'};
    }
    if (typeof updatedAt === 'number' && !Number.isFinite(updatedAt)) {
      return {valid: false, error: 'before.updatedAt number must be finite'};
    }

    parsedMessage.before = {
      sessionId: before.sessionId,
      updatedAt,
    };
  }

  return {valid: true, data: parsedMessage};
}

